import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        String[][] ops = new String[(int) n][2];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = next();
            }
        }

        Map<Long, Integer> freq = new HashMap<>();
        List<ArrayDeque<Long>> groups = new ArrayList<>();
        for (int i = 0; i < n + 2; i++) groups.add(new ArrayDeque<>());
        int maxFreq = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (ops[i][0].equals("push")) {
                long x = Long.parseLong(ops[i][1]);
                int f = freq.merge(x, 1, Integer::sum);
                if (f > maxFreq) maxFreq = f;
                groups.get(f).push(x);
            } else {
                long x = groups.get(maxFreq).pop();
                freq.merge(x, -1, Integer::sum);
                if (groups.get(maxFreq).isEmpty()) maxFreq--;
                sb.append(x).append("\n");
            }
        }
        System.out.print(sb);
    }
}
